# Optimization script for Yang et al. (2009) inlet TKE profiles.
# Reads inlet/outlet profiles generated by OpenFOAM, optimizes C1 and C2,
# updates the OpenFOAM input files, and stores convergence metrics.
# Managed by the external loop in the script "runFit.sh"

library(readr)
library(stringr)
library(tidyr)
library(ggplot2)
library(patchwork) 

#==============================================================================
# 1. Defining/reading input and output 
#==============================================================================

scriptArgs = commandArgs(trailingOnly=TRUE)
relErrTol <- as.numeric(scriptArgs[1]) 
calcGrads <- scriptArgs[2] 
fileABL <- "0.orig/include/ABLConditions"
fileMesh <- "system/blockMeshDict"
fileU <- "0.orig/U"
fileLogOptim <- "fitOut/logOptim.csv" 
figInOut0 <- "fitOut/inOut_0.png"
figInOutLast <- "fitOut/inOut_last.png"

#==============================================================================
# 2. Reading input data
#==============================================================================

## 2.1 Reading inlet and outlet profiles

source("R/readInletOutlet.R")
fieldsInOut <- readInletOutlet()
Z <-fieldsInOut$z
nZ <-  length(Z)

## 2.2 Reading optimization parameters

# Read the initial C1 and C2 values to be used as optimization first guess
findParamVal <- function(fileIn, paramString){
    lines <- readLines(fileIn)  
    findP <- str_match(lines, paste0("^",paramString,".*?([0-9]+\\.?[0-9]*)"))[, 2]
	  lineP <- !is.na(findP)
	  P <- parse_number(findP[lineP])
	  return(P)
}

C1 <- findParamVal(fileABL, "C1")
C2 <- findParamVal(fileABL, "C2")
# reading also other parameters
Uref <- findParamVal(fileABL, "Uref")
Zref <- findParamVal(fileABL, "Zref")
z0 <- findParamVal(fileABL, "z0")
kappa <- findParamVal(fileABL, "kappa")
Cmu <- findParamVal(fileABL, "Cmu")
zTop <- findParamVal(fileMesh, "zMax")
# calculating ustar
Ustar <- Uref * kappa /log((Zref+z0)/z0)

#==============================================================================
# 3. Defining the optimization problem
#==============================================================================

# Fit the analytical Yang TKE inlet profile to the computed outlet profile.

## 3.1 Defining the analytical Yang profile
TKEzInlet_4fit <- function(z, c1, c2){ 
  tkeIn <- (Ustar^2)/sqrt(Cmu)*sqrt(c1*log((z+z0)/z0)+c2)
  return(tkeIn)
}

## 3.2 Defining the objective function
functionToMinimize <- function(c){
    kfit <- TKEzInlet_4fit(Z, c[1], c[2])
    f <- mean((kfit - fieldsInOut$kOutlet)^2)
    return(f)
}

## 3.3 Defining optimization constraints (sqrt argument must be non-negative)
Ui <- cbind(log((Z+z0)/z0)  , rep(1, nZ))
Ci <- rep(0, nZ) 

#==============================================================================
# 4. Running the constrained optimization for C1 and C2
#==============================================================================

o <- constrOptim(theta = c(C1,C2),
                 f = functionToMinimize, 
                 ui = Ui, ci = Ci, 
                 grad    = NULL,            
		 method = "Nelder-Mead"
)

C1_new <- o$par[1]
C2_new <- o$par[2]

#==============================================================================
# 5. Computing and writing convergence metrics
#==============================================================================

## 5.1 Computing vertical weights by re-building the Z array
nZmesh   <- findParamVal(fileMesh, "nz")
zMinMesh <- findParamVal(fileMesh, "zMin")
zMaxMesh <- findParamVal(fileMesh, "zMax")
rMesh    <- findParamVal(fileMesh, "zTotalExpansion")   

Hmesh <- zMaxMesh - zMinMesh
rho   <- rMesh^(1/(nZmesh - 1))
if (abs(rho - 1) < 1e-12) {
  h <- rep(Hmesh / nZmesh, nZmesh) 
} else {
  h1 <- Hmesh * (1 - rho) / (1 - rho^nZmesh)
  h  <- h1 * rho^(0:(nZmesh - 1))
}
w <- h / sum(h)
stopifnot(length(w) == nZ)

## 5.2 Computing fit residual, normalized 
rrmsdFit <-  sqrt(o$value)/mean(fieldsInOut$kOutlet)

## 5.3 Computing RRMSD values
in_v  <- c("kInlet", "UxInlet", "epsilonInlet")
out_v <- c("kOutlet", "UxOutlet", "epsilonOutlet")

RRMSD <- sapply(seq_along(in_v), function(i) {
  inlet  <- fieldsInOut[[ in_v[i] ]]
  outlet <- fieldsInOut[[ out_v[i] ]]

  outletRefW  <- sum(w * outlet)                      
  sqrRelError <- sum(w * (inlet - outlet)^2) / (outletRefW)^2
  return(sqrt(sqrRelError))
})
names(RRMSD) <- paste0("RRMSD_", c("k", "Ux", "eps"))

## 5.4 Computing gradient sign discordance for k (m s-2) 
dZ <- diff(Z)
ddzkInlet  <- diff(fieldsInOut$kInlet)  / dZ
ddzkOutlet <- diff(fieldsInOut$kOutlet) / dZ

# Fraction of the profile length with opposite gradient signs
gradientSignDiscordance <- sum(dZ[ddzkInlet * ddzkOutlet < 0]) / sum(dZ)
names(gradientSignDiscordance) <- "GradSignDisc_k"

## 5.5 Checking the stopping criterion
stopLoop <- if (RRMSD["RRMSD_k"] < relErrTol) 1 else 0

## 5.6 Writing optimization results: optimized coefficients and convergence metrics
rowData   <- c(C1_new, C2_new, rrmsdFit, RRMSD, gradientSignDiscordance, stopLoop)
colNames  <- c("C1_new", "C2_new", "rrmsdFit", names(RRMSD), names(gradientSignDiscordance), "stopLoop")

# write header at the first iteration
if (!file.exists(fileLogOptim)){
  write.table(t(colNames), fileLogOptim, row.names = F, col.names = F, sep = " ")
}
# append values
write.table(t(rowData), fileLogOptim, row.names = F, col.names = F, sep = " ", append = T)

#==============================================================================
# 6. Updating OpenFOAM input files
#==============================================================================

## 6.1 Computing analytical top gradients (optional)
if(calcGrads){
  # Quantity inside Yang's sqrt
  argSqrtTop <- C1_new * log((zTop + z0)/z0) + C2_new
  # Shear stress @top
  topShearStress <- Ustar^2 * sqrt(argSqrtTop)
  # Analytical top gradients
  topGradK <-
    (Ustar^2 * C1_new) /
    (2 * sqrt(Cmu) * (zTop + z0) * sqrt(argSqrtTop))
  topGradEpsilon <- (Ustar^3)/(kappa * (zTop + z0)^2) *
    (C1_new / (2 * sqrt(argSqrtTop)) - sqrt(argSqrtTop))
}

## 6.2 Updating the ABL conditions: C1, C2 (mandatory); top shear stress and gradients (optional)
lines <- readLines(fileABL)
updatedLines <- str_replace(lines, "^(C1\\s+)[^\\s;]+", 
                            paste0("C1 ", as.character(C1_new)))
updatedLines <- str_replace(updatedLines, "^(C2\\s+)[^\\s;]+", 
                            paste0("C2 ", as.character(C2_new)))
if(calcGrads){
  updatedLines <- str_replace(updatedLines, "^(topGradK\\s+)[^\\s;]+", 
                            paste0("topGradK ", topGradK))
  updatedLines <- str_replace(updatedLines, "^(topGradEpsilon\\s+)[^\\s;]+", 
                            paste0("topGradEpsilon ", topGradEpsilon))
  # if(calcGrads) update also U shear stress
  linesU <- readLines(fileU)
  updatedLinesU <- str_replace(
    linesU,
    "^(\\s*tau\\s+)\\([^\\)]*\\)",
    paste0("        tau             (", topShearStress, " 0 0)")
  )
  writeLines(updatedLinesU, fileU)
}
writeLines(updatedLines, con = fileABL)

#==============================================================================
# 7. Generating comparison plots
#==============================================================================

source("R/plot.R")

# 7.1 Generating plots: inlet-outlet profiles + fitted profile for k
plots <- generatePlots()

# 7.2 Saving plots
savePlots(plots)